SubmenuDef.definition:
BaseDef<'submenu'> & Searchable & MenuState & {
    /** Static nodes (sync mode). Mutually exclusive with `loader`. */
    nodes?: NodeDef<TChild>[];
    /** Async node loader (async mode). Mutually exclusive with `nodes`. */
